<?php
$login_error='';if(isset($_GET['logout'])){session_regenerate_id(true);unset($_SESSION['admin_id']);flash('You have signed out.');header('Location: ?page=admin');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['login'])){verify_csrf();$email=filter_var(trim((string)($_POST['email']??'')),FILTER_VALIDATE_EMAIL);$q=db()->prepare('SELECT id,password_hash FROM users WHERE email=? AND role="admin"');$q->execute([$email?:'']);$u=$q->fetch();if($u&&password_verify((string)($_POST['password']??''),$u['password_hash'])){session_regenerate_id(true);$_SESSION['admin_id']=(int)$u['id'];header('Location: ?page=admin');exit;} $login_error='Email or password was not recognised.';}
if(admin_logged_in()&&$_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['action'])){verify_csrf();$id=(int)($_POST['booking_id']??0);$act=$_POST['action'];$q=db()->prepare('SELECT * FROM bookings WHERE id=?');$q->execute([$id]);$b=$q->fetch();if($b){if($act==='cancel'&&$b['status']==='confirmed'){db()->prepare("UPDATE bookings SET status='cancelled',refund_amount=total_fare WHERE id=?")->execute([$id]);db()->prepare("UPDATE trip_seats ts JOIN booking_seats bs ON bs.trip_seat_id=ts.id SET ts.status='available' WHERE bs.booking_id=?")->execute([$id]);db()->prepare('INSERT INTO booking_events(booking_id,event_type,note,created_at) VALUES(?,?,?,NOW())')->execute([$id,'cancelled','Staff cancelled reservation; full demo refund recorded']);flash('Booking cancelled and full sample refund recorded.');}elseif($act==='change'&&$b['status']==='confirmed'){$newTrip=(int)($_POST['new_trip']??0);$t=trip_by_id($newTrip);if($t){$oldSeats=db()->prepare('SELECT seat_code FROM booking_seats WHERE booking_id=?');$oldSeats->execute([$id]);$seatCodes=$oldSeats->fetchAll(PDO::FETCH_COLUMN);$pdo=db();$pdo->beginTransaction();try{$pdo->prepare("UPDATE trip_seats ts JOIN booking_seats bs ON bs.trip_seat_id=ts.id SET ts.status='available' WHERE bs.booking_id=?")->execute([$id]);$pdo->prepare('DELETE FROM booking_seats WHERE booking_id=?')->execute([$id]);$up=$pdo->prepare("UPDATE trip_seats SET status='reserved' WHERE trip_id=? AND seat_code=? AND status='available'");$insert=$pdo->prepare('INSERT INTO booking_seats(booking_id,trip_seat_id,seat_code) VALUES(?,?,?)');$find=$pdo->prepare('SELECT id FROM trip_seats WHERE trip_id=? AND seat_code=?');foreach($seatCodes as $sc){$up->execute([$newTrip,$sc]);if(!$up->rowCount())throw new RuntimeException();$find->execute([$newTrip,$sc]);$insert->execute([$id,$find->fetchColumn(),$sc]);}$pdo->prepare('UPDATE bookings SET trip_id=?,total_fare=? WHERE id=?')->execute([$newTrip,fare_for($t,$b['concession'],count($seatCodes)),$id]);$pdo->commit();flash('Booking changed to the new sample departure.');}catch(Throwable $e){$pdo->rollBack();flash('Change failed: seats may be unavailable. Booking was restored.','error');}}}header('Location: ?page=admin');exit;}}
if(admin_logged_in()){$bookings=db()->query('SELECT b.*,p.full_name,t.depart_at,r.train_code,a.name origin,c.name destination FROM bookings b JOIN passengers p ON p.booking_id=b.id JOIN trips t ON t.id=b.trip_id JOIN routes r ON r.id=t.route_id JOIN stations a ON a.id=r.from_station_id JOIN stations c ON c.id=r.to_station_id ORDER BY b.created_at DESC LIMIT 40')->fetchAll();$trips=db()->query('SELECT t.id,t.depart_at,r.train_code,a.name origin,c.name destination FROM trips t JOIN routes r ON r.id=t.route_id JOIN stations a ON a.id=r.from_station_id JOIN stations c ON c.id=r.to_station_id WHERE t.depart_at>NOW() ORDER BY t.depart_at')->fetchAll();$counts=db()->query("SELECT COUNT(*) total, SUM(status='confirmed') confirmed, SUM(status='cancelled') cancelled FROM bookings")->fetch();}
?>
<?php if(!admin_logged_in()): ?><section class="page-banner"><div class="container"><p class="eyebrow">STAFF ACCESS</p><h1>Operations <em>sign in.</em></h1><p>Manage sample routes and reservation requests.</p></div></section><section class="container content-section"><form class="login-card" method="post"><?= csrf_field() ?><input type="hidden" name="login" value="1"><p class="eyebrow">ADMINISTRATOR</p><h2>Welcome back.</h2><?php if($login_error): ?><p class="inline-error"><?= h($login_error) ?></p><?php endif; ?><label>Email<input type="email" name="email" autocomplete="username" required></label><label>Password<input type="password" name="password" autocomplete="current-password" required></label><button class="button primary full-width">Sign in →</button><small>Demo login: admin@crs.test · Admin123!</small></form></section><?php else: ?><section class="page-banner"><div class="container admin-banner"><div><p class="eyebrow">STAFF WORKSPACE</p><h1>Operations <em>overview.</em></h1><p>Reservations and sample fare administration.</p></div><div><a class="button secondary" href="?page=routes">Manage routes</a> <a class="text-link" href="?page=admin&logout=1">Sign out ↗</a></div></div></section><section class="container content-section"><div class="stats-grid"><div class="stat-card"><small>ALL BOOKINGS</small><strong><?= (int)$counts['total'] ?></strong></div><div class="stat-card"><small>CONFIRMED</small><strong><?= (int)$counts['confirmed'] ?></strong></div><div class="stat-card"><small>CANCELLED / REFUNDED</small><strong><?= (int)$counts['cancelled'] ?></strong></div></div><div class="section-head admin-list-head"><div><p class="eyebrow">RESERVATION ADMINISTRATION</p><h2>Recent bookings</h2></div></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Reference / passenger</th><th>Journey</th><th>Date</th><th>Fare / status</th><th>Actions</th></tr></thead><tbody><?php foreach($bookings as $b): ?><tr><td><strong><?= h($b['reference']) ?></strong><small><?= h($b['full_name']) ?></small></td><td><?= h($b['origin']) ?> → <?= h($b['destination']) ?><small><?= h($b['train_code']) ?></small></td><td><?= h(date('d M · H:i',strtotime($b['depart_at']))) ?></td><td><?= money((float)$b['total_fare']) ?><small><?= h($b['status']) ?><?= $b['refund_amount']>0?' · refund '.money((float)$b['refund_amount']):'' ?></small></td><td><?php if($b['status']==='confirmed'): ?><form method="post" class="inline-admin"><?= csrf_field() ?><input type="hidden" name="booking_id" value="<?= (int)$b['id'] ?>"><select name="new_trip" aria-label="New train for <?= h($b['reference']) ?>"><?php foreach($trips as $t): ?><option value="<?= (int)$t['id'] ?>"><?= h($t['train_code'].' · '.$t['origin'].' '.$t['depart_at']) ?></option><?php endforeach; ?></select><button name="action" value="change" class="button secondary tiny">Change</button><button name="action" value="cancel" class="button danger tiny" data-confirm="Cancel booking and record a full demo refund?">Cancel / refund</button></form><?php else: ?><span class="muted">Closed</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php endif; ?>
